  const persistPreferences = async () => api("/api/meal-planner/preferences", { method: "PUT", body: JSON.stringify({ allergies: split(allergies), intolerances: split(intolerances), disliked_ingredients: split(dislikes), dietary_preferences: diet === "Any" ? [] : [diet], default_cuisine: cuisine, available_time_minutes: Number(availableTime || 30), budget_level: budget, servings: Number(servings || 1), activity_level: session?.user?.activity_level || "moderate" }) });
