  const swap = async type => { try { const data = await api("/api/meal-planner/swap-meal", { method: "POST", body: JSON.stringify({ meal_type: type, current_plan: plan, preferences: preferences() }) }); setPlan(data.plan); } catch (e) { Alert.alert("Could not swap meal", e.message); } };
