  if (feature === "assistant") return <AssistantScreen onBack={back} />;
  if (feature === "meal-planner") return <MealPlannerScreen onBack={back} />;
  if (feature === "care") return <CareTeamScreen user={user} onBack={back} />;
  if (feature === "security") return <SecurityScreen onBack={back} />;
  if (feature === "privacy") return <ConsentCenterScreen onBack={back} onStatusChange={onConsentStatusChange} />;
  if (feature === "support") return <SupportSafetyScreen user={user} onBack={back} />;
  if (feature === "emergency") return <EmergencyScreen onBack={back} />;
  if (feature === "appointments") return <AppointmentsScreen user={user} onUnauthorized={onUnauthorized} onBack={back} />;
  if (feature === "patients") return <ClinicianPatientsScreen onBack={back} />;
