  if (feature === "staff-emergency") return <StaffEmergencyScreen onBack={back} />;
  if (feature === "timeline") return <HealthTimelineScreen api={api} user={user} onBack={back} />;
  if (feature === "record-intelligence") return <RecordIntelligenceScreen api={api} user={user} onBack={back} />;
  if (feature === "appointment-center") return <AppointmentCenterScreen api={api} user={user} onBack={back} />;
  if (feature === "referrals") return <CrossConsultationsScreen api={api} user={user} onBack={back} />;
  if (feature === "health-tips") return <HealthTipsScreen api={api} onBack={back} />;
  if (feature === "cycle") return <CycleTrackingScreen api={api} user={user} onBack={back} />;
  if (feature === "grocery") return <GroceryListScreen api={api} onBack={back} />;
  if (feature === "credentialing") return <ClinicianApprovalScreen api={api} onBack={back} />;
