  if (feature === "profile") return <View style={s.flex}><View style={s.inlineBack}><Pressable onPress={back}><Text style={s.link}>‹ All features</Text></Pressable></View><ProfileScreen user={user} onLogout={onLogout} /></View>;
  const items = [
    ["appointments", "Appointments", "Calendar, bookings, and video visits", "◷"],
    ["appointment-center", "Appointment center", "Reminders, rescheduling, cancellation, and visit notes", "◴"],
    ["timeline", "Health timeline", user.role === "patient" ? "Your complete care history" : "Review patient care events chronologically", "↕"],
    ["record-intelligence", "Record intelligence", "Details, version history, search, and report comparison", "▤"],
    ["referrals", "Cross consultations", user.role === "clinician" ? "Refer patients and manage specialist responses" : "Track specialist consultation activity", "⇄"],
    ["health-tips", "Health tips", "Practical educational wellness guidance", "✦"],
    ...(user.role === "patient" ? [["care", "Care connections", "Find and connect with clinicians", "◎"], ["grocery", "Smart grocery list", "Combine ingredients from scheduled meal plans", "≡"], ["cycle", "Cycle wellness", "Private tracking, logs, and nutrition context", "◉"]] : []),
    ...(user.role === "clinician" ? [["prescriptions", "Prescriptions", "Create and manage medication plans", "Rx"], ["availability", "Consultation hours", "Schedule, duration, and availability", "◫"], ["staff-emergency", "Emergency response", "Monitor and respond to patient SOS", "!"], ["credentialing", "Clinician credentialing", "Approval status and professional credentials", "✓"]] : []),
    ...(user.role === "admin" ? [["admin", "Admin workspace", "Analytics, approvals, users, audit, and communications", "◇"], ["staff-emergency", "Emergency operations", "Monitor and coordinate all SOS alerts", "!"]] : []),
    ["profile", "Profile", "Personal and clinical account details", "○"],
    ["security", "Active sessions", "Review signed-in devices", "▣"],
    ["privacy", "Privacy & consent", "Review policies and AI acknowledgements", "✓"],
    ["support", "Support & safety", "Intended use, help, and emergency guidance", "?"],
  ];
  return <ScrollView contentContainerStyle={s.screenContent}><Header eyebrow="CARECONNECT PRO" title="All features" subtitle={`Tools available for your ${user.role} account.`} /><View style={s.featureGrid}>{items.map(([key, title, subtitle, icon]) => <Pressable key={key} onPress={() => setFeature(key)} style={s.featureCard}><View style={s.featureIcon}><Text style={s.featureIconText}>{icon}</Text></View><View style={s.flex}><Text style={s.infoTitle}>{title}</Text><Text style={s.infoText}>{subtitle}</Text></View><Text style={s.chevron}>›</Text></Pressable>)}</View></ScrollView>;
