const patientTabs = [["home", "⌂", "Home"], ["records", "▤", "Records"], ["prescriptions", "Rx", "Prescriptions"], ["meal-planner", "🥗", "Meals"], ["more", "•••", "More"]];
const clinicianTabs = [["home", "⌂", "Home"], ["patients", "♙", "Patients"], ["clinical-search", "⌕", "Clinical Search"], ["more", "•••", "More"]];
const adminTabs = [["home", "⌂", "Home"], ["admin", "◇", "Admin"], ["emergency-ops", "!", "SOS"], ["more", "•••", "More"]];
function Shell({ user, onLogout }) {
  const [tab, setTab] = useState("home"); const [overlay, setOverlay] = useState(null); const [assistant, setAssistant] = useState(false); const [unread, setUnread] = useState(0); const [consentReady, setConsentReady] = useState(null); const unauthorized = useCallback(() => { Alert.alert("Session expired", "Please sign in again."); onLogout(false); }, [onLogout]);
  useEffect(() => { Promise.all(CONSENT_TYPES.map(type => api(`/api/consents/${type}`))).then(items => setConsentReady(items.every(x => x.accepted))).catch(e => { if (e.status === 401) unauthorized(); else setConsentReady(false); }); }, [unauthorized]);
  useEffect(() => { const load = () => api("/api/notifications/unread-count").then(x => setUnread(x.unread_count || 0)).catch(() => {}); load(); const timer = setInterval(load, 60000); return () => clearInterval(timer); }, []);
  const activeTabs = user.role === "admin" ? adminTabs : user.role === "clinician" ? clinicianTabs : patientTabs;
  const screens = { home: <HomeScreen user={user} onUnauthorized={unauthorized} />, records: <RecordsScreen user={user} onUnauthorized={unauthorized} />, prescriptions: <PrescriptionsScreen user={user} />, "meal-planner": <MealPlannerScreen />, patients: <ClinicianPatientsScreen />, "clinical-search": <ClinicalSearchScreen />, admin: <AdminWorkspaceScreen api={api} />, "emergency-ops": <StaffEmergencyScreen />, more: <MoreScreen user={user} onLogout={onLogout} onUnauthorized={unauthorized} onConsentStatusChange={setConsentReady} /> };
  const sos = () => setOverlay(user.role === "patient" ? "emergency" : "staff-emergency");
  if (consentReady === null) return <SafeAreaView style={s.app}><View style={s.state}><ActivityIndicator color={c.blue} size="large" /><Text style={s.stateText}>Checking current privacy choices…</Text></View></SafeAreaView>;
  if (!consentReady) return <SafeAreaView style={s.app}><ConsentCenterScreen required onAccepted={() => setConsentReady(true)} /></SafeAreaView>;
  return <SafeAreaView style={s.app}><View style={s.topBar}><View style={s.brandRow}><View style={s.logo360}><Text style={s.logoCross}>+</Text></View><View><Text style={s.topBrand}>Care <Text style={s.brand360}>360</Text></Text><Text style={s.brandTagline}>{user.role === "admin" ? "OPERATIONS WORKSPACE" : user.role === "clinician" ? "CLINICAL WORKSPACE" : "CONNECTED HEALTH"}</Text></View></View><View style={s.topActions}><Pressable accessibilityLabel="Emergency SOS" onPress={sos} style={s.sosButton}><Text style={s.sosText}>{user.role === "patient" ? "SOS" : "ALERTS"}</Text></Pressable><Pressable accessibilityLabel="Messages" onPress={() => setOverlay("messages")} style={s.topIconButton}><Text style={s.topIcon}>✉</Text></Pressable><Pressable accessibilityLabel="Updates" onPress={() => setOverlay("updates")} style={s.topIconButton}><Text style={s.topIcon}>●</Text>{unread > 0 && <Text style={s.topBadge}>{unread > 9 ? "9+" : unread}</Text>}</Pressable></View></View><View style={s.flex}>{overlay === "messages" ? <MessagesScreen user={user} onBack={() => setOverlay(null)} /> : overlay === "updates" ? <View style={s.flex}><FeatureHeader title="Updates" subtitle="Notifications that need your attention." onBack={() => setOverlay(null)} /><NotificationsScreen hideHeader onUnauthorized={unauthorized} /></View> : overlay === "emergency" ? <EmergencyScreen onBack={() => setOverlay(null)} /> : overlay === "staff-emergency" ? <StaffEmergencyScreen onBack={() => setOverlay(null)} /> : screens[tab]}</View>{!overlay && user.role === "patient" && <Pressable accessibilityLabel="Open Health Assistant" onPress={() => setAssistant(true)} style={s.assistantFab}><Text style={s.assistantFabIcon}>✦</Text><View><Text style={s.assistantFabTitle}>Ask Care 360</Text><Text style={s.assistantFabSub}>Health Assistant</Text></View></Pressable>}{!overlay && <View style={s.tabBar}>{activeTabs.map(([key, icon, label]) => <Pressable accessibilityRole="tab" accessibilityState={{ selected: tab === key }} key={key} onPress={() => setTab(key)} style={s.tab}><Text style={[s.tabIcon, tab === key && s.tabActive]}>{icon}</Text><Text style={[s.tabLabel, tab === key && s.tabActive]}>{label}</Text>{tab === key && <View style={s.tabIndicator} />}</Pressable>)}</View>}<Modal visible={assistant} transparent animationType="slide" onRequestClose={() => setAssistant(false)}><Pressable style={s.modalShade} onPress={() => setAssistant(false)} /><View style={s.assistantSheet}><View style={s.sheetHandle} /><AssistantScreen popup onBack={() => setAssistant(false)} /></View></Modal></SafeAreaView>;
}

export default function App() {
  const [user, setUser] = useState(null); const [restoring, setRestoring] = useState(true);
  useEffect(() => { (async () => { try { if (await SecureStore.getItemAsync(TOKEN_KEY)) setUser(await api("/api/auth/me")); } catch { await SecureStore.deleteItemAsync(TOKEN_KEY); } finally { setRestoring(false); } })(); }, []);
  const logout = async (notifyServer = true) => { if (notifyServer) await api("/api/auth/logout", { method: "POST" }).catch(() => {}); await SecureStore.deleteItemAsync(TOKEN_KEY); setUser(null); };
  if (restoring) return <View style={s.splash}><View style={s.brandMark}><Text style={s.brandMarkText}>+</Text></View><ActivityIndicator color={c.blue} /></View>;
  return <><StatusBar style={user ? "dark" : "light"} />{user ? <Shell user={user} onLogout={logout} /> : <LoginScreen onAuthenticated={setUser} />}</>;
}

